        self.name = name
        self.age = age

my_dog = Dog("Buddy", 3)
print(my_dog.name)  # Buddy

class Dog:
    def __init__(self, name):
        self.name = name

    def bark(self):
        print(f"{self.name} says Woof!")

my_dog = Dog("Buddy")
my_dog.bark()  # Buddy says Woof!

class Person:
    def __init__(self, name):
        self.name = name

    def greet(self, other):
        print(f"{self.name} says Hi to {other}")

p1 = Person("Alice")
p1.greet("Bob")

class Car:
    def __init__(self, brand):
        self.brand = brand

    def info(self):
        print(f"This is a {self.brand}")

car1 = Car("Toyota")
car2 = Car("Honda")
car1.info()  # This is a Toyota
car2.info()  # This is a Honda

class Student:
    def __init__(self, name, grade):
        self.name = name
        self.grade = grade

    def study(self, hours):
        print(f"{self.name} studies for {hours} hours")

    def pass_test(self):
        print(f"{self.name} passed the test!")

student = Student("Alice", "A")
student.study(3)
student.pass_test()
